const q = indexedDB.open('entregas', 1);
q.onupgradeneeded = () => {
  const pedidos = q.result.createObjectStore('pedidos', { keyPath: 'id' });
  pedidos.createIndex('porEstado', 'estado');
};
q.onsuccess = () => {
  const db = q.result;
  // leer: todos los que están «en ruta», sin recorrer los otros
  const lectura = db.transaction('pedidos').objectStore('pedidos').index('porEstado').getAll('en ruta');
  lectura.onsuccess = () => console.log(lectura.result.length);
  // escribir: cambiar un solo pedido
  const tx = db.transaction('pedidos', 'readwrite');
  tx.objectStore('pedidos').put({ id: 7, cliente: 'Cliente 7', estado: 'entregado', bultos: 8 });
  tx.oncomplete = () => console.log('guardado');
};

